    [Fact]
    public void ReferenceScenario_Etapa4Nodes_PresentWithCorrectPositionAndEntrouPor()
    {
        var path = ReferenceScenario.Path!;
        var pathById = path.ToDictionary(n => n.Id, StringComparer.Ordinal);

        // Posições esperadas (0-based = passo - 1) conforme a fixture
        var expected = new (int PassoZeroBased, string NodeId, string? ExpectedEntrouPor)[]
        {
            (14, "_LeuhgFqVEfG5K7mY0I3I6w", "fluxo"),   // passo 15 — Iniciar Decisions (linkThrow)
            (15, "_CI6l0VqREfG5K7mY0I3I6w", "link"),    // passo 16 — Iniciar Decisions (linkCatch, NOEQ)
