            (20, "_30jAcFqVEfG5K7mY0I3I6w", "fluxo"),   // passo 21 — Verificar Retorno Decisions
        };

        foreach (var (idx, nodeId, expectedEntrouPor) in expected)
        {
            Assert.True(pathById.ContainsKey(nodeId),
                $"Nó '{nodeId}' declarado no card não encontrado no path[] de {ReferenceScenarioId}.");

            var node = path[idx];
            Assert.Equal(nodeId, node.Id);

            if (expectedEntrouPor is null)
