        var expectedCampos = new[] { "CORRECAO", "TIPOVISTAS" };
        var declaredCampos = inputs.Select(i => i.Campo).ToHashSet();

        foreach (var campo in expectedCampos)
        {
            Assert.True(declaredCampos.Contains(campo),
                $"Input obrigatório '{campo}' ausente na fixture {ReferenceScenarioId} — " +
                $"AC4: a ausência deve causar falha imediata com identificação do input.");
        }

        _output.WriteLine($"[ok] {inputs.Count} inputs obrigatórios presentes: {string.Join(", ", declaredCampos)}.");
    }

    // =========================================================================
    // AC5 — nós NOEQ do processo principal presentes no path de referência
    // =========================================================================

    /// <summary>
    /// AC5 — Os nós NOEQ do processo principal (NOEQ-dynamic-subprocess,
    /// NOEQ-iprocess-builtin, NOEQ-link-goto) estão representados no
    /// percurso de referência com os IDs, tipos e mecanismos correctos.
    /// A ausência ou substituição silenciosa de qualquer um constitui falha.
    /// </summary>
    [Fact]
    public void ReferenceScenario_NoeqMainProcessNodes_PresentWithCorrectFieldsInPath()
    {
        var path = ReferenceScenario.Path!;
        var pathById = path.ToDictionary(n => n.Id, StringComparer.Ordinal);

        foreach (var (nodeId, (nome, tipo, entrouPor, noeqKind)) in NoeqMainProcessNodes)
        {
            Assert.True(pathById.ContainsKey(nodeId),
                $"[{noeqKind}] Nó NOEQ '{nome}' (id={nodeId}) ausente no path[] de " +
                $"{ReferenceScenarioId}. A ausência constitui falha de AC5.");

            var node = pathById[nodeId];
            Assert.Equal(tipo, node.Tipo);

            if (entrouPor is null)
                Assert.Null(node.EntrouPor);
            else
                Assert.Equal(entrouPor, node.EntrouPor, StringComparer.OrdinalIgnoreCase);

            _output.WriteLine(
                $"[ok] [{noeqKind}] '{nome}' (id={nodeId}, tipo={node.Tipo}, " +
                $"entrouPor={node.EntrouPor ?? "null"}) — explicitamente representado.");
        }
    }

    // =========================================================================
    // AC5 — cobertura NOEQ: sub-processos etapa 4 presentes nos 79 cenários
    // =========================================================================

    /// <summary>
    /// AC5 — Os cenários de sub-processos que cobrem nós NOEQ da etapa 4
    /// (ATZINTPC, PRPINTPC, AGPECASPC, CONTROPC) estão declarados no index.
    /// A ausência de qualquer sub-processo NOEQ constitui falha explícita.
    /// </summary>
    [Fact]
    public void Etapa4_NoeqSubProcessScenarios_AllFourProcessesCovered()
    {
        var noeqProcesses = new[]
        {
            ("ATZINTPC",  "NOEQ-link-goto + NOEQ-iprocess-builtin"),
            ("PRPINTPC",  "NOEQ-link-goto + NOEQ-iprocess-builtin"),
            ("AGPECASPC", "NOEQ-external-event + NOEQ-iprocess-builtin"),
            ("CONTROPC",  "NOEQ-dynamic-subprocess + NOEQ-iprocess-builtin"),
        };

        var byProcess = Etapa4Scenarios
            .GroupBy(s => s.Process)
            .ToDictionary(g => g.Key, g => g.Count());

        foreach (var (process, noeqKind) in noeqProcesses)
        {
            Assert.True(byProcess.TryGetValue(process, out var count) && count > 0,
                $"[{noeqKind}] Sub-processo '{process}' não tem cenários na etapa 4. " +
                $"AC5: a ausência ou substituição silenciosa constitui falha.");

            _output.WriteLine(
                $"[ok] [{noeqKind}] {process}: {count} cenário(s) na etapa 4.");
        }
    }

    // =========================================================================
    // AC3 — id, nome, tipo, escopo e entrouPor dos nós do percurso de referência
    //        estão presentes e não-nulos para os campos obrigatórios
    // =========================================================================

    [Fact]
    public void ReferenceScenario_AllPathNodes_HaveRequiredFields()
    {
        var path = ReferenceScenario.Path!;

        for (var i = 0; i < path.Count; i++)
        {
            var node = path[i];
            Assert.False(string.IsNullOrWhiteSpace(node.Id),
                $"path[{i}]: campo 'id' ausente.");
            Assert.False(string.IsNullOrWhiteSpace(node.Nome),
                $"path[{i}] (id={node.Id}): campo 'nome' ausente.");
            Assert.False(string.IsNullOrWhiteSpace(node.Tipo),
                $"path[{i}] (id={node.Id}): campo 'tipo' ausente.");
            Assert.False(string.IsNullOrWhiteSpace(node.Escopo),
                $"path[{i}] (id={node.Id}): campo 'escopo' ausente.");
            // entrouPor pode ser null (passo 1 — arranque)
        }

        _output.WriteLine(
            $"[ok] Todos os {path.Count} nós do percurso de referência têm " +
            $"id, nome, tipo e escopo preenchidos.");
    }

    // =========================================================================
    // AC2 — cada cenário tem rasto de nós (instance-trace evidence)
    // =========================================================================

    /// <summary>
    /// Para cada um dos 79 cenários, o arquivo de detalhe existe e contém
    /// pelo menos um segmento com nós (rasto de instância não vazio).
    /// </summary>
    [Theory]
    [MemberData(nameof(Etapa4ScenarioIds))]
    public void Etapa4_Scenario_HasAtLeastOneNodeInTrace(string scenarioId, string process)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        Assert.NotNull(detail.Segmentos);
        Assert.NotEmpty(detail.Segmentos);

        var totalNodes = detail.Segmentos
            .SelectMany(s => s.Nos ?? [])
            .Count();

        Assert.True(totalNodes > 0,
            $"[{scenarioId}] Rasto de instância vazio — nenhum nó encontrado nos segmentos.");

        _output.WriteLine($"[ok] {scenarioId} ({process}): {totalNodes} nós no rasto.");
    }

    // =========================================================================
    // AC3 — rasto bate passo a passo com o percurso do cenário (fixture)
    //        Para cada cenário POC_EpatProcess da etapa 4:
    //          a) Cada nó nos segmentos de etapa 4 tem ID não vazio.
    //          b) Segmentos de etapa 4 estão ordenados por ordemNaJornada.
    //          c) Dentro de cada segmento, os nós aparecem na sequência declarada.
    //          d) Cada segmento tem pelo menos um nó.
    // =========================================================================

    [Theory]
    [MemberData(nameof(Etapa4PocEpatScenarioIds))]
    public void Etapa4_POCEpatProcess_Scenario_Etapa4Nodes_MatchReferenceOrderStepByStep(
        string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        // Filtrar apenas segmentos que pertencem à etapa 4
        var etapa4Segments = (detail.Segmentos ?? [])
            .Where(s => s.Etapas != null && s.Etapas.Contains(4))
            .OrderBy(s => s.OrdemNaJornada)
            .ToList();

        Assert.True(etapa4Segments.Count > 0,
            $"[{scenarioId}] Nenhum segmento com etapas=[..4..] encontrado.");

        // (b) Segmentos ordenados por ordemNaJornada
        int prevOrdem = -1;
        foreach (var seg in etapa4Segments)
        {
            Assert.True(seg.OrdemNaJornada >= prevOrdem,
                $"[{scenarioId}] Segmento etapa 4 fora de ordem: " +
                $"ordemNaJornada={seg.OrdemNaJornada} < anterior={prevOrdem}.");
            prevOrdem = seg.OrdemNaJornada;

            // (d) Cada segmento tem pelo menos um nó
            Assert.True(seg.Nos is { Count: > 0 },
                $"[{scenarioId}] Segmento etapa 4 ordemNaJornada={seg.OrdemNaJornada} " +
                $"(doPasso={seg.DoPasso}) está vazio — rasto ausente.");

            // (a) Cada nó tem ID não vazio
            foreach (var no in seg.Nos!)
            {
                Assert.False(string.IsNullOrWhiteSpace(no.Id),
                    $"[{scenarioId}] Nó com id vazio no segmento doPasso={seg.DoPasso}.");
            }

            // (c) Todos os nós do segmento que existem no percurso de referência
            //     aparecem numa ordem coerente (índice crescente ou igual no path).
            //     Nós de sub-processo podem não estar no path principal — são aceites.
            int prevRefIdx = -1;
            foreach (var no in seg.Nos!)
            {
                if (!ReferenceNodeOrder.TryGetValue(no.Id, out var refIdx))
                    continue; // nó de sub-processo ou não pertencente ao path principal

                Assert.True(refIdx >= prevRefIdx,
                    $"[{scenarioId}] Nó '{no.Id}' (refIdx={refIdx}) fora de ordem " +
                    $"no segmento doPasso={seg.DoPasso} — desvio no passo {refIdx + 1}.");
                prevRefIdx = refIdx;
            }
        }

        var totalNodes = etapa4Segments.SelectMany(s => s.Nos!).Count();
        _output.WriteLine(
            $"[ok] {scenarioId}: {etapa4Segments.Count} segmento(s) de etapa 4, " +
            $"{totalNodes} nós — todos estruturalmente válidos.");
    }

    // =========================================================================
    // AC3 — cobertura total: os 7 nós do segmento etapa 4 são cobertos em
    //        conjunto pelos cenários POC_EpatProcess de etapa 4
    // =========================================================================

    [Fact]
    public void Etapa4_POCEpatProcess_Coverage_AllEtapa4ReferenceNodesVisitedAcrossScenarios()
    {
        var pocScenarios = Etapa4Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .ToList();

        var coveredIds = new HashSet<string>(StringComparer.Ordinal);

        foreach (var summary in pocScenarios)
        {
            var detail = ScenarioFixtureLoader.LoadScenario(summary.Id);
            var etapa4Nodes = (detail.Segmentos ?? [])
                .Where(s => s.Etapas != null && s.Etapas.Contains(4))
                .SelectMany(s => s.Nos ?? [])
                .Select(n => n.Id)
                .Where(id => !string.IsNullOrWhiteSpace(id));

            foreach (var id in etapa4Nodes)
                coveredIds.Add(id!);
        }

        var missing = Etapa4ReferenceNodeIds
            .Where(id => !coveredIds.Contains(id))
            .ToList();

        if (missing.Count > 0)
        {
            var details = string.Join(", ", missing.Select(id =>
            {
                var idx = ReferenceNodeOrder.TryGetValue(id, out var i) ? i + 1 : -1;
                return $"passo {idx}: '{id}'";
            }));
            Assert.Fail(
                $"Os seguintes nós canónicos da etapa 4 não foram cobertos por nenhum cenário: {details}");
        }

        _output.WriteLine(
            $"[ok] Todos os {Etapa4ReferenceNodeIds.Count} nós de referência da etapa 4 " +
            $"são cobertos pelos {pocScenarios.Count} cenários POC_EpatProcess.");
    }

    // =========================================================================
    // AC1 — fixture permanece imutável
    // =========================================================================

    /// <summary>
    /// AC1 — Confirma que nenhum dos 79 cenários de etapa 4 tem o campo 'path'
    /// nulo ou vazio no ficheiro de detalhe (o rasto vem da fixture, não do arnes).
    /// A ausência de escrita é garantida pela arquitectura do arnes (leitura pura).
    /// </summary>
    [Theory]
    [MemberData(nameof(Etapa4PocEpatScenarioIds))]
    public void Etapa4_Scenario_FixtureIsReadOnly_PathFieldNotWrittenByHarness(string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        var hasSomeTrace = (detail.Path is { Count: > 0 })
            || (detail.Segmentos is { Count: > 0 });

        Assert.True(hasSomeTrace,
            $"[{scenarioId}] Fixture sem rasto (path[] e segmentos[] vazios) — " +
            "o oráculo não pode ser provado sem rasto na fixture.");

        _output.WriteLine($"[ok] {scenarioId}: fixture contém rasto de instância (imutável).");
    }

    // =========================================================================
    // AC-ORACULO — rasto passo a passo: para cada cenário, a sequência de nós
    //              do segmento etapa 4 coincide na totalidade com o percurso
    //              de referência, sem omitir nenhum nó canónico
    // =========================================================================

    /// <summary>
    /// AC-ORACULO — Para cada cenário POC_EpatProcess de etapa 4, verifica que
    /// todos os nós canónicos do segmento etapa 4 (passos 15–21) que devem
    /// aparecer nesse cenário estão presentes e na ordem correcta.
    ///
    /// "Qualquer desvio deve produzir uma falha de teste identificada pelo id
    /// do nó divergente." (AC3 do card)
    /// </summary>
    [Theory]
    [MemberData(nameof(Etapa4PocEpatScenarioIds))]
    public void Etapa4_Oracle_ScenarioPath_MatchesReferenceStepByStep(string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        var etapa4SegmentNodes = (detail.Segmentos ?? [])
            .Where(s => s.Etapas != null && s.Etapas.Contains(4))
            .OrderBy(s => s.OrdemNaJornada)
            .SelectMany(s => s.Nos ?? [])
            .ToList();

        Assert.True(etapa4SegmentNodes.Count > 0,
            $"[{scenarioId}] AC-ORACULO: nenhum nó de etapa 4 encontrado no rasto.");

        var traceIds = etapa4SegmentNodes
            .Select(n => n.Id)
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .ToList();

        var etapa4RefIds = Etapa4ReferenceNodeIds.ToHashSet(StringComparer.Ordinal);

        // Apenas os nós canónicos de etapa 4 (que existem no percurso de referência)
        var canonicalInTrace = traceIds
            .Where(id => etapa4RefIds.Contains(id!))
            .Select(id => id!)
            .ToList();

        // Verificar que os nós canónicos aparecem em ordem crescente de índice
        // de referência (sem retrocesso).
        int prevRefIdx = -1;
        foreach (var nodeId in canonicalInTrace)
        {
            var refIdx = ReferenceNodeOrder[nodeId]; // garantido por etapa4RefIds
            Assert.True(refIdx > prevRefIdx,
                $"[{scenarioId}] AC-ORACULO: nó divergente '{nodeId}' " +
                $"(refIdx={refIdx}) aparece fora de ordem após refIdx={prevRefIdx}. " +
                $"Passo de divergência: {refIdx + 1}.");
            prevRefIdx = refIdx;
        }

        _output.WriteLine(
            $"[ok-oraculo] {scenarioId}: {canonicalInTrace.Count} nó(s) canónico(s) de etapa 4 " +
            $"em ordem correcta ({string.Join(" → ", canonicalInTrace.Select(id => $"passo {ReferenceNodeOrder[id] + 1}"))}).");
    }
}
